from control_full import *
from transport_contact import measure
import numpy as np,sys,json
A=np.load('/app/work/edge_reference.npz')['actions'];S=None
# start; first duration; second duration; lift duration; drag dx; descend dz; lift dz; left dy,dz; fixed orientation weight
P=np.array([160,50,30,50,-.24,-.10,.20,.10,.12,1.])
def run(p,save=None):
 global S
 if S is None:S=Session('insert_normal',instance='/app/instance.npz')
 s=S;s.reset();c=Controller(s);d=s.data;starts=None;score=0;bar=0;edge=0;acts=[];states=[];poses=[]
 for t in range(500):
  u=c.lo+(A[t]+1)*c.span/2
  if t>=p[0]:
   if starts is None:starts=d.xpos[c.palms].copy();rots=d.xmat[c.palms].reshape(2,3,3).copy()
   a=np.clip((t-p[0])/p[1],0,1);b=np.clip((t-p[0]-p[1])/p[2],0,1);v=np.clip((t-p[0]-p[1]-p[2])/p[3],0,1)
   for side in range(2):
    pos=starts[side].copy()
    if side==1:pos+=np.array([p[4]*(.5*a+.5*b),0,p[5]*b+p[6]*v])
    else:pos+=np.array([.35*p[4]*a,p[7]*a,p[8]*a])
    u[c.armidx[side]]=c.ik(side,pos,rots[side] if p[9]>.5 else None,n=6)
  act=c.norm(u);_,_,done=s.step(act);score+=measure(d)
  if t>=p[0]:
   bar+=np.clip((np.mean(d.site_xpos[[11,12],2])-.98)/.12,0,1)
   edge+=np.clip((.60-np.mean(d.site_xpos[[11,12],0]))/.2,0,1)
  if save:acts.append(act);states.append(d.qpos.copy())
  if save and t in [139,179,209,239,279,329,399,499]:poses.append(s._snapshot())
  if done:break
 if save:np.savez(save,actions=acts,states=states,poses=poses,p=p,score=score);print(score,bar,edge,c.details(),flush=True)
 return np.array([-score,-bar,-edge])
if __name__=='__main__':run(P,'/app/output/drag_test.npz')
PY
